mapper.select:
SELECT COUNT(*)
FROM punch_correction_request
WHERE employee_id = #{employeeId}
  AND request_month = #{requestMonth}
  AND status IN ('PENDING', 'APPROVED')

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM attendance_group_assignment assignment
    JOIN attendance_group_revision group_revision
      ON group_revision.attendance_group_revision_id =
            assignment.attendance_group_revision_id
    JOIN attendance_group scoped_group
      ON scoped_group.attendance_group_id =
            group_revision.attendance_group_id
    JOIN attendance_assignment_timeline assignment_state
      ON assignment_state.attendance_group_assignment_id =
            assignment.attendance_group_assignment_id
     AND assignment_state.state = 'ACTIVE'
    JOIN attendance_group_timeline group_state
      ON group_state.attendance_group_id =
            scoped_group.attendance_group_id
     AND group_state.state = 'ACTIVE'
    JOIN calendar_publication_timeline publication
      ON publication.work_calendar_id =
            group_revision.work_calendar_id
     AND publication.state = 'PUBLISHED'
    JOIN work_calendar_day calendar_day
      ON calendar_day.work_calendar_version_id =
            publication.work_calendar_version_id
     AND calendar_day.business_date = #{businessDate}
    WHERE assignment.employee_id = #{employeeId}
      AND assignment.effective_from <= #{businessDate}
      AND assignment.created_at <= #{knowledgeAsOf}
      AND assignment_state.business_effective_from
            <= #{businessDate}
      AND assignment_state.recorded_at <= #{knowledgeAsOf}
      AND group_state.business_effective_from <= #{businessDate}
      AND group_state.recorded_at <= #{knowledgeAsOf}
      AND publication.business_effective_from <= #{businessDate}
      AND publication.recorded_at <= #{knowledgeAsOf}
      AND calendar_day.day_type IN ('WORKDAY', 'SPECIAL_WORKDAY')
      AND NOT EXISTS (
          SELECT 1
          FROM attendance_group_assignment successor
          WHERE successor.supersedes_assignment_id =
                    assignment.attendance_group_assignment_id
            AND successor.effective_from <= #{businessDate}
            AND successor.created_at <= #{knowledgeAsOf}
      )
      AND NOT EXISTS (
          SELECT 1
          FROM attendance_assignment_timeline newer
          WHERE newer.attendance_group_assignment_id =
                    assignment.attendance_group_assignment_id
            AND newer.business_effective_from <= #{businessDate}
            AND newer.recorded_at <= #{knowledgeAsOf}
            AND newer.event_sequence >
                    assignment_state.event_sequence
      )
      AND NOT EXISTS (
          SELECT 1
          FROM attendance_group_timeline newer
          WHERE newer.attendance_group_id =
                    scoped_group.attendance_group_id
            AND newer.business_effective_from <= #{businessDate}
            AND newer.recorded_at <= #{knowledgeAsOf}
            AND newer.event_sequence > group_state.event_sequence
      )
      AND NOT EXISTS (
          SELECT 1
          FROM calendar_publication_timeline newer
          WHERE newer.work_calendar_id =
                    group_revision.work_calendar_id
            AND newer.business_effective_from <= #{businessDate}
            AND newer.recorded_at <= #{knowledgeAsOf}
            AND newer.event_sequence > publication.event_sequence
      )
) THEN TRUE ELSE FALSE END
